Section At.
Variables r c s N psi rho0 D Nrr Frr Hrr : R.
Hypotheses (Hr : 0 < r) (HN : 0 < N) (Hpsi : 0 < psi).

(* the jets at the face: f = h = 1 and every first derivative zero, the density rho0 fixing psi_rr,
   and the shift amplitude b = D N / psi^2 *)
Definition jets (G : R -> R -> R -> R -> R -> R -> R -> R -> R -> R -> R -> R -> R -> R -> R -> R -> R) : R :=
  G r c s N 0 Nrr psi 0 (- (2 * PI * psi^5 * rho0)) 1 0 Frr 1 0 Hrr (D * N / psi^2).

Ltac nz := repeat split; try apply PI_neq0; try lra; try (apply pow_nonzero; lra);
           try (apply Rgt_not_eq; apply pow_lt; lra).

Lemma face_00 : jets G_00 = 8 * PI * (rho0).
Proof.
  unfold jets, G_00. field. nz.
Qed.

Lemma face_01 : jets G_01 = 8 * PI * (- (D * c * rho0)).
Proof.
  unfold jets, G_01. field. nz.
Qed.

Lemma face_02 : jets G_02 = 8 * PI * (D * s * Hrr / (16 * PI * psi^4)).
Proof.
  unfold jets, G_02. field. nz.
Qed.

Lemma face_11 : jets G_11 = 8 * PI * (D^2 * c^2 * rho0).
Proof.
  unfold jets, G_11. field. nz.
Qed.

Lemma face_12 : jets G_12 = 8 * PI * (- (D^2 * c * s * Hrr / (16 * PI * psi^4))).
Proof.
  unfold jets, G_12. field. nz.
Qed.

Lemma face_22 : jets G_22 = 8 * PI * (Nrr / (8 * PI * N * psi^4) - rho0 / 2 + D^2 * c^2 * (rho0 - Frr / (8 * PI * psi^4))).
Proof.
  unfold jets, G_22. field. nz.
Qed.

Lemma face_33 : jets G_33 = 8 * PI * (Nrr / (8 * PI * N * psi^4) - rho0 / 2 + D^2 * c^2 * (rho0 - Frr / (8 * PI * psi^4))).
Proof.
  unfold jets, G_33. field. nz.
Qed.

(* the energy flux the free-fall observer sees is (E, -T0r, -T0th, 0); the dominant condition makes it causal *)
Theorem face_drift :
  0 < rho0 ->
  (jets G_01 / (8 * PI))^2 + (jets G_02 / (8 * PI))^2 <= (jets G_00 / (8 * PI))^2 ->
  D^2 * c^2 <= 1.
Proof.
  intros Hrho Hflux.
  rewrite face_00, face_01, face_02 in Hflux.
  replace (8 * PI * rho0 / (8 * PI)) with rho0 in Hflux by (field; apply PI_neq0).
  replace (8 * PI * - (D * c * rho0) / (8 * PI)) with (- (D * c * rho0)) in Hflux
    by (field; apply PI_neq0).
  set (t := 8 * PI * (D * s * Hrr / (16 * PI * psi ^ 4)) / (8 * PI)) in Hflux.
  assert (0 <= t^2) by (apply pow2_ge_0).
  assert ((D * c * rho0)^2 <= rho0^2) as Hb by nra.
  assert (0 < rho0^2) by (apply pow_lt; lra).
  replace ((D * c * rho0)^2) with ((D^2 * c^2) * rho0^2) in Hb by ring.
  nra.
Qed.

(* at the light speed the face data above carry dust of density rho0 moving with (1, -cos th) on the frame *)
Lemma face_dust : D = 1 -> Hrr = 0 -> Frr = 8 * PI * psi^4 * rho0 -> Nrr = 4 * PI * N * psi^4 * rho0 ->
  jets G_00 / (8 * PI) = rho0 /\
  jets G_01 / (8 * PI) = - (c * rho0) /\
  jets G_02 / (8 * PI) = 0 /\
  jets G_11 / (8 * PI) = c * c * rho0 /\
  jets G_12 / (8 * PI) = 0 /\
  jets G_22 / (8 * PI) = 0 /\
  jets G_33 / (8 * PI) = 0.
Proof.
  intros E1 E2 E3 E4.
  rewrite face_00, face_01, face_02, face_11, face_12, face_22, face_33, E1, E2, E3, E4.
  repeat split; field; nz.
Qed.

(* the face theorem's bound is sharp: face data drifting at the light speed meet every condition *)
Theorem face_sharp :
  0 <= rho0 -> -1 <= c <= 1 -> D = 1 -> Hrr = 0 -> Frr = 8 * PI * psi^4 * rho0 ->
  Nrr = 4 * PI * N * psi^4 * rho0 -> energy_conditions (jets G_00 / (8 * PI)) (jets G_01 / (8 * PI)) (jets G_02 / (8 * PI)) (jets G_11 / (8 * PI)) (jets G_12 / (8 * PI)) (jets G_22 / (8 * PI)) (jets G_33 / (8 * PI)).
Proof.
  intros Hrho Hc E1 E2 E3 E4.
  destruct (face_dust E1 E2 E3 E4) as (-> & -> & -> & -> & -> & -> & ->).
  apply dust_conditions; assumption.
Qed.

End At.
End Face.

(* The drag family's Einstein tensor.  The metric in (t, r, c, ph), c = cos th, with w = 1 - c^2, over the
   atoms r, N, psi, w, held nonzero, and the other variables c, N_r, N_rr, psi_r, psi_rr, f, f_r, f_rr, h, h_r, h_rr: g_t, its inverse
   gi_t, the derivatives of each variable along the four coordinates rules_t, and the frame f0, f1, f2, f3 with
   e_th over sin th and e_ph times sin th.  The check computes the Einstein tensor of g_t from its first and
   second formal derivatives by the curvature formulas, on Laurent polynomials, and compares it on each pair
   of frame vectors with W_*, G_* with the frame's powers of sin th, modulo c^2 = 1 - w. *)
