Definition frames_t : list ((nat -> lp) * (nat -> lp) * rx) := ((f0, f0, ast_00) :: (f0, f1, ast_01) :: (f0, f2, ast_02) :: (f1, f1, ast_11) :: (f1, f2, ast_12) :: (f2, f2, ast_22) :: (f3, f3, ast_33) :: nil)%list.

Lemma check : curv_check (same_rx 3) g_t gi_t rules_t frames_t = true.
Proof. vm_compute. reflexivity. Qed.

(* the Einstein tensor of g_t on two vectors, with the variables' values A and O *)
Definition einstein (A O : list R) (va vb : nat -> lp) : R :=
  along (fun a b => lev A O (g_t a b)) (fun a b => lev A O (gi_t a b))
    (fun a b k => lev A O (jet1 g_t rules_t a b k)) (fun a b k l => lev A O (jet2 g_t rules_t a b k l))
    (fun a => lev A O (va a)) (fun b => lev A O (vb b)).

Lemma frame_value A O : List.Forall (fun x => x <> 0) A -> nth 0 O 1 ^ 2 = 1 - nth 3 A 1 ->
  forall va vb t, In (va, vb, t) frames_t -> einstein A O va vb = rx_eval A O t.
Proof.
  intros HA Hc. exact (proj2 (curv_check_correct (same_rx 3) (rx_eval A O) A O g_t gi_t rules_t frames_t HA
    (same_rx_correct A O 3 HA Hc) check)).
Qed.

Theorem einstein_00 (r c s N N_r N_rr psi psi_r psi_rr f f_r f_rr h h_r h_rr : R) :
  r <> 0 -> N <> 0 -> psi <> 0 -> s <> 0 -> s * s = 1 - c ^ 2 ->
  einstein (r :: N :: psi :: s * s :: nil) (c :: N_r :: N_rr :: psi_r :: psi_rr :: f :: f_r :: f_rr :: h :: h_r :: h_rr :: nil) f0 f0 = G_00 r c s N N_r N_rr psi psi_r psi_rr f f_r f_rr h h_r h_rr.
Proof.
  intros H0 H1 H2 Hs Hcs.
  assert (HA : List.Forall (fun x => x <> 0) (r :: N :: psi :: s * s :: nil))
    by (repeat constructor; try assumption; apply Rmult_integral_contrapositive_currified; assumption).
  assert (Hc : nth 0 (c :: N_r :: N_rr :: psi_r :: psi_rr :: f :: f_r :: f_rr :: h :: h_r :: h_rr :: nil) 1 ^ 2 = 1 - nth 3 (r :: N :: psi :: s * s :: nil) 1) by (cbn [nth]; rewrite Hcs; ring).
  rewrite (frame_value _ _ HA Hc f0 f0 ast_00 ltac:(unfold frames_t; cbn [In]; left; reflexivity)).
  change (rx_eval (r :: N :: psi :: s * s :: nil) (c :: N_r :: N_rr :: psi_r :: psi_rr :: f :: f_r :: f_rr :: h :: h_r :: h_rr :: nil) ast_00) with (W_00 r c (s * s) N N_r N_rr psi psi_r psi_rr f f_r f_rr h h_r h_rr).
  unfold W_00, G_00. field; repeat split; first [assumption | apply pow_nonzero; assumption | apply Rmult_integral_contrapositive_currified; assumption].
Qed.

