Definition frames_t : list ((nat -> lp) * (nat -> lp) * rx) := ((fk, fk, ast_kk) :: (fk, fl, ast_kl) :: (fl, fl, ast_ll) :: (fk, f2, ast_k2) :: (fl, f2, ast_l2) :: (f2, f2, ast_22) :: (f3, f3, ast_33) :: nil)%list.

Lemma check : curv_check (same_rx 2) g_t gi_t rules_t frames_t = true.
Proof. vm_compute. reflexivity. Qed.

(* the Einstein tensor of g_t on two vectors, with the variables' values A and O *)
Definition einstein (A O : list R) (va vb : nat -> lp) : R :=
  along (fun a b => lev A O (g_t a b)) (fun a b => lev A O (gi_t a b))
    (fun a b k => lev A O (jet1 g_t rules_t a b k)) (fun a b k l => lev A O (jet2 g_t rules_t a b k l))
    (fun a => lev A O (va a)) (fun b => lev A O (vb b)).

Lemma frame_value A O : List.Forall (fun x => x <> 0) A -> nth 0 O 1 ^ 2 = 1 - nth 2 A 1 ->
  forall va vb t, In (va, vb, t) frames_t -> einstein A O va vb = rx_eval A O t.
Proof.
  intros HA Hc. exact (proj2 (curv_check_correct (same_rx 2) (rx_eval A O) A O g_t gi_t rules_t frames_t HA
    (same_rx_correct A O 2 HA Hc) check)).
Qed.

