Lemma radial_ok : radial_check 16 7 radial_prog radial_constants radial_atoms radial_rows = true.
Proof. rewrite <- Fast.fradial_check_eq. vm_cast_no_check (eq_refl true). Qed.

Lemma radial_atoms_eq r : map (fun e => Tree.eval e (r :: nil)) radial_atoms = (G_00_00 r (j_N r) (j_N_r r) (j_N_rr r) (j_psi r) (j_psi_r r) (j_psi_rr r) (j_f r) (j_f_r r) (j_f_rr r) :: G_00_20 r (j_N r) (j_N_r r) (j_N_rr r) (j_psi r) (j_psi_r r) (j_psi_rr r) (j_f r) (j_f_r r) (j_f_rr r) :: G_01_10 r (j_N r) (j_N_r r) (j_N_rr r) (j_psi r) (j_psi_r r) (j_psi_rr r) (j_f r) (j_f_r r) (j_f_rr r) :: G_02_01 r (j_N r) (j_N_r r) (j_N_rr r) (j_psi r) (j_psi_r r) (j_psi_rr r) (j_f r) (j_f_r r) (j_f_rr r) :: G_11_00 r (j_N r) (j_N_r r) (j_N_rr r) (j_psi r) (j_psi_r r) (j_psi_rr r) (j_f r) (j_f_r r) (j_f_rr r) :: G_11_20 r (j_N r) (j_N_r r) (j_N_rr r) (j_psi r) (j_psi_r r) (j_psi_rr r) (j_f r) (j_f_r r) (j_f_rr r) :: G_12_11 r (j_N r) (j_N_r r) (j_N_rr r) (j_psi r) (j_psi_r r) (j_psi_rr r) (j_f r) (j_f_r r) (j_f_rr r) :: G_22_00 r (j_N r) (j_N_r r) (j_N_rr r) (j_psi r) (j_psi_r r) (j_psi_rr r) (j_f r) (j_f_r r) (j_f_rr r) :: G_22_20 r (j_N r) (j_N_r r) (j_N_rr r) (j_psi r) (j_psi_r r) (j_psi_rr r) (j_f r) (j_f_r r) (j_f_rr r) :: G_33_00 r (j_N r) (j_N_r r) (j_N_rr r) (j_psi r) (j_psi_r r) (j_psi_rr r) (j_f r) (j_f_r r) (j_f_rr r) :: G_33_20 r (j_N r) (j_N_r r) (j_N_rr r) (j_psi r) (j_psi_r r) (j_psi_rr r) (j_f r) (j_f_r r) (j_f_rr r) :: rho r :: nil)%list.
Proof. reflexivity. Qed.

Lemma row_n0 r th : 1 <= r <= 2 -> 0 <= th <= PI -> 0 <= tE r th - mu r - Rabs (ta r th) - Rabs (td r th).
Proof.
  intros Hr Hth.
  generalize (radial_nonneg 16 7 radial_prog radial_constants radial_atoms radial_rows radial_ok r th Hr Hth 0 ltac:(simpl; lia)).
  rewrite radial_atoms_eq. exact (fun h => h).
Qed.

Lemma row_n1 r th : 1 <= r <= 2 -> 0 <= th <= PI -> 0 <= tS r th + mu r - Rabs (ta r th) - Rabs (tx r th).
Proof.
