(* every energy condition, for every observer, at every point of the wall *)
Theorem shell_energy_conditions r th : 1 <= r <= 2 -> 0 <= th <= PI -> energy_conditions (tE r th) (ta r th) (td r th) (tS r th) (tx r th) (tT r th) (tP r th).
Proof.
  intros Hr Hth.
  apply (certified (tE r th) (ta r th) (td r th) (tS r th) (tx r th) (tT r th) (tP r th) (mu r) (lam r)).
  - pose proof (row_n0 r th Hr Hth). lra.
  - pose proof (row_n1 r th Hr Hth). lra.
  - pose proof (row_n2 r th Hr Hth). lra.
  - pose proof (row_n3 r th Hr Hth). lra.
  - pose proof (row_m r th Hr Hth). lra.
  - pose proof (row_s r th Hr Hth). lra.
  - pose proof (row_d0 r th Hr Hth). lra.
  - pose proof (row_d1 r th Hr Hth). lra.
  - pose proof (row_d2 r th Hr Hth). lra.
  - pose proof (row_d3 r th Hr Hth). lra.
  - pose proof (row_l r th Hr Hth). lra.
Qed.

(* G_* are the drag family's G_* at this shell's jets, and so its Einstein tensor on the frame there *)
Definition bridge_00 : rx := (RAdd (RDiv (RAdd (RMul (RA 0) (RAdd (RMul (RMul (RZ (-1)) (RPow (RO 7) 2)) (RPow (RA 2) 5)) (RMul (RMul (RZ (-16)) (RO 5)) (RPow (RA 1) 2)))) (RMul (RMul (RZ (-32)) (RO 4)) (RPow (RA 1) 2))) (RMul (RMul (RMul (RZ 4) (RA 0)) (RPow (RA 1) 2)) (RPow (RA 2) 5))) (RMul (RMul (RO 0) (RO 0)) (RDiv (RMul (RMul (RA 0) (RPow (RA 2) 3)) (RAdd (RMul (RA 2) (RAdd (RMul (RA 2) (RPow (RO 7) 2)) (RMul (RMul (RMul (RZ 16) (RO 6)) (RO 7)) (RO 4)))) (RMul (RMul (RZ 48) (RPow (RO 6) 2)) (RPow (RO 4) 2)))) (RMul (RMul (RMul (RZ 4) (RA 0)) (RPow (RA 1) 2)) (RPow (RA 2) 5))))).
Definition bridge_00_family : rx := (RAdd (RDiv (RAdd (RMul (RPow (RA 1) 2) (RAdd (RMul (RMul (RZ (-32)) (RO 4)) (RA 0)) (RMul (RMul (RZ (-16)) (RO 5)) (RPow (RA 0) 2)))) (RMul (RPow (RA 2) 5) (RAdd (RAdd (RMul (RO 6) (RAdd (RAdd (RMul (RZ (-1)) (RO 6)) (RMul (RZ 2) (RO 6))) (RMul (RMul (RZ (-2)) (RO 7)) (RA 0)))) (RMul (RO 6) (RAdd (RMul (RZ (-1)) (RO 6)) (RMul (RMul (RZ 2) (RO 7)) (RA 0))))) (RMul (RMul (RZ (-1)) (RPow (RO 7) 2)) (RPow (RA 0) 2))))) (RMul (RMul (RMul (RZ 4) (RPow (RA 1) 2)) (RPow (RA 2) 5)) (RPow (RA 0) 2))) (RMul (RMul (RO 0) (RO 0)) (RDiv (RMul (RPow (RA 2) 3) (RAdd (RMul (RA 2) (RAdd (RMul (RO 6) (RAdd (RAdd (RMul (RMul (RMul (RZ (-32)) (RO 6)) (RO 4)) (RA 0)) (RMul (RMul (RMul (RZ 16) (RO 7)) (RO 4)) (RPow (RA 0) 2))) (RMul (RMul (RMul (RZ 32) (RO 6)) (RO 4)) (RA 0)))) (RMul (RA 2) (RAdd (RAdd (RMul (RO 6) (RAdd (RAdd (RAdd (RMul (RZ (-10)) (RO 6)) (RMul (RZ 5) (RO 6))) (RMul (RMul (RZ 2) (RO 7)) (RA 0))) (RMul (RMul (RZ 8) (RO 7)) (RA 0)))) (RMul (RO 6) (RAdd (RAdd (RMul (RZ 5) (RO 6)) (RMul (RMul (RZ (-8)) (RO 7)) (RA 0))) (RMul (RMul (RZ (-2)) (RO 7)) (RA 0))))) (RMul (RPow (RO 7) 2) (RPow (RA 0) 2)))))) (RMul (RMul (RMul (RZ 48) (RPow (RO 6) 2)) (RPow (RO 4) 2)) (RPow (RA 0) 2)))) (RMul (RMul (RMul (RZ 4) (RPow (RA 1) 2)) (RPow (RA 2) 5)) (RPow (RA 0) 2))))).
Lemma G_00_family (r c s N N_r N_rr psi psi_r psi_rr f f_r f_rr : R) : r <> 0 -> N <> 0 -> psi <> 0 ->
  G_00 r c s N N_r N_rr psi psi_r psi_rr f f_r f_rr = DragEinstein.G_00 r c s N N_r N_rr psi psi_r psi_rr f f_r f_rr f f_r f_rr.
Proof.
  intros H0 H1 H2.
  change (rx_eval (r :: N :: psi :: nil) (c :: s :: N_r :: N_rr :: psi_r :: psi_rr :: f :: f_r :: f_rr :: nil) bridge_00 = rx_eval (r :: N :: psi :: nil) (c :: s :: N_r :: N_rr :: psi_r :: psi_rr :: f :: f_r :: f_rr :: nil) bridge_00_family).
