Definition bridge_33 : rx := (RAdd (RDiv (RAdd (RMul (RA 1) (RAdd (RMul (RA 1) (RAdd (RMul (RMul (RZ 4) (RO 2)) (RPow (RA 2) 2)) (RMul (RMul (RMul (RZ 8) (RA 1)) (RA 2)) (RO 4)))) (RMul (RPow (RA 2) 5) (RAdd (RMul (RMul (RZ (-16)) (RO 4)) (RPow (RO 6) 2)) (RMul (RMul (RMul (RZ (-4)) (RO 6)) (RO 7)) (RA 2)))))) (RMul (RMul (RA 1) (RA 0)) (RAdd (RMul (RA 1) (RAdd (RMul (RA 1) (RAdd (RMul (RZ (-8)) (RPow (RO 4) 2)) (RMul (RMul (RZ 8) (RA 2)) (RO 5)))) (RMul (RMul (RZ 4) (RO 3)) (RPow (RA 2) 2)))) (RMul (RMul (RZ (-1)) (RPow (RO 7) 2)) (RPow (RA 2) 6))))) (RMul (RMul (RMul (RZ 4) (RA 0)) (RPow (RA 1) 3)) (RPow (RA 2) 6))) (RMul (RMul (RO 0) (RO 0)) (RDiv (RAdd (RMul (RA 0) (RAdd (RMul (RPow (RA 2) 5) (RAdd (RMul (RMul (RMul (RZ 16) (RO 2)) (RO 4)) (RPow (RO 6) 2)) (RMul (RMul (RMul (RMul (RZ 4) (RO 2)) (RO 6)) (RO 7)) (RA 2)))) (RMul (RMul (RA 1) (RPow (RA 2) 4)) (RAdd (RMul (RA 2) (RAdd (RMul (RO 6) (RAdd (RMul (RMul (RZ (-40)) (RO 7)) (RO 4)) (RMul (RMul (RZ (-16)) (RO 6)) (RO 5)))) (RMul (RA 2) (RAdd (RMul (RZ (-3)) (RPow (RO 7) 2)) (RMul (RMul (RZ (-4)) (RO 6)) (RO 8)))))) (RMul (RMul (RZ (-32)) (RPow (RO 6) 2)) (RPow (RO 4) 2)))))) (RMul (RMul (RA 1) (RPow (RA 2) 5)) (RAdd (RMul (RMul (RZ 16) (RO 4)) (RPow (RO 6) 2)) (RMul (RMul (RMul (RZ 4) (RO 6)) (RO 7)) (RA 2))))) (RMul (RMul (RMul (RZ 4) (RA 0)) (RPow (RA 1) 3)) (RPow (RA 2) 6))))).
Definition bridge_33_family : rx := (RAdd (RDiv (RMul (RA 1) (RAdd (RMul (RA 1) (RAdd (RMul (RA 1) (RAdd (RMul (RA 2) (RAdd (RMul (RMul (RZ 8) (RO 4)) (RA 0)) (RMul (RMul (RZ 8) (RO 5)) (RPow (RA 0) 2)))) (RMul (RMul (RZ (-8)) (RPow (RO 4) 2)) (RPow (RA 0) 2)))) (RMul (RPow (RA 2) 2) (RAdd (RMul (RMul (RZ 4) (RO 2)) (RA 0)) (RMul (RMul (RZ 4) (RO 3)) (RPow (RA 0) 2)))))) (RMul (RPow (RA 2) 5) (RAdd (RMul (RA 2) (RAdd (RAdd (RMul (RO 6) (RAdd (RAdd (RMul (RZ (-1)) (RO 6)) (RMul (RZ (-2)) (RO 6))) (RMul (RMul (RZ (-2)) (RO 7)) (RA 0)))) (RMul (RO 6) (RAdd (RAdd (RMul (RZ 3) (RO 6)) (RMul (RMul (RZ (-4)) (RO 7)) (RA 0))) (RMul (RMul (RZ 2) (RO 7)) (RA 0))))) (RMul (RMul (RZ (-1)) (RPow (RO 7) 2)) (RPow (RA 0) 2)))) (RMul (RMul (RMul (RMul (RZ (-16)) (RO 6)) (RO 6)) (RO 4)) (RA 0)))))) (RMul (RMul (RMul (RZ 4) (RPow (RA 1) 3)) (RPow (RA 2) 6)) (RPow (RA 0) 2))) (RMul (RMul (RO 0) (RO 0)) (RDiv (RAdd (RMul (RPow (RA 2) 5) (RAdd (RMul (RMul (RO 6) (RA 2)) (RAdd (RAdd (RMul (RMul (RMul (RZ (-4)) (RO 2)) (RO 6)) (RA 0)) (RMul (RMul (RMul (RZ 4) (RO 2)) (RO 6)) (RA 0))) (RMul (RMul (RMul (RZ 4) (RO 2)) (RO 7)) (RPow (RA 0) 2)))) (RMul (RMul (RMul (RMul (RZ 16) (RO 2)) (RO 4)) (RPow (RO 6) 2)) (RPow (RA 0) 2)))) (RMul (RMul (RA 1) (RPow (RA 2) 4)) (RAdd (RMul (RA 2) (RAdd (RMul (RO 6) (RAdd (RAdd (RMul (RO 6) (RAdd (RMul (RMul (RZ (-24)) (RO 4)) (RA 0)) (RMul (RMul (RZ (-16)) (RO 5)) (RPow (RA 0) 2)))) (RMul (RMul (RMul (RZ (-40)) (RO 7)) (RO 4)) (RPow (RA 0) 2))) (RMul (RMul (RMul (RZ 40) (RO 6)) (RO 4)) (RA 0)))) (RMul (RA 2) (RAdd (RAdd (RAdd (RMul (RO 6) (RAdd (RAdd (RAdd (RAdd (RO 6) (RMul (RZ 6) (RO 6))) (RMul (RMul (RZ (-8)) (RO 7)) (RA 0))) (RMul (RMul (RZ (-4)) (RO 8)) (RPow (RA 0) 2))) (RMul (RMul (RZ 6) (RO 7)) (RA 0)))) (RMul (RO 6) (RAdd (RAdd (RMul (RZ (-7)) (RO 6)) (RMul (RMul (RZ (-2)) (RO 7)) (RA 0))) (RMul (RMul (RZ 8) (RO 7)) (RA 0))))) (RMul (RPow (RO 7) 2) (RPow (RA 0) 2))) (RMul (RMul (RZ (-4)) (RPow (RO 7) 2)) (RPow (RA 0) 2)))))) (RMul (RMul (RMul (RZ (-32)) (RPow (RO 6) 2)) (RPow (RO 4) 2)) (RPow (RA 0) 2))))) (RMul (RMul (RMul (RZ 4) (RPow (RA 1) 3)) (RPow (RA 2) 6)) (RPow (RA 0) 2))))).
Lemma G_33_family (r c s N N_r N_rr psi psi_r psi_rr f f_r f_rr : R) : r <> 0 -> N <> 0 -> psi <> 0 ->
  G_33 r c s N N_r N_rr psi psi_r psi_rr f f_r f_rr = DragEinstein.G_33 r c s N N_r N_rr psi psi_r psi_rr f f_r f_rr f f_r f_rr.
Proof.
  intros H0 H1 H2.
  change (rx_eval (r :: N :: psi :: nil) (c :: s :: N_r :: N_rr :: psi_r :: psi_rr :: f :: f_r :: f_rr :: nil) bridge_33 = rx_eval (r :: N :: psi :: nil) (c :: s :: N_r :: N_rr :: psi_r :: psi_rr :: f :: f_r :: f_rr :: nil) bridge_33_family).
  apply rx_same_correct; [repeat constructor; assumption | vm_compute; reflexivity].
Qed.

Theorem einstein_33 (r c s N N_r N_rr psi psi_r psi_rr f f_r f_rr  : R) :
  r <> 0 -> N <> 0 -> psi <> 0 -> s <> 0 -> s * s = 1 - c ^ 2 ->
  DragEinstein.einstein (r :: N :: psi :: s * s :: nil) (c :: N_r :: N_rr :: psi_r :: psi_rr :: f :: f_r :: f_rr :: f :: f_r :: f_rr :: nil) DragEinstein.f3 DragEinstein.f3 = s ^ 2 * G_33 r c s N N_r N_rr psi psi_r psi_rr f f_r f_rr.
Proof.
  intros. rewrite G_33_family by assumption. apply DragEinstein.einstein_33; assumption.
Qed.

(* the radial jets are derivatives of one another *)
Lemma j_N_derive r : 1 <= r <= 2 -> is_derive j_N r (j_N_r r).
Proof.
  intros Hr. unfold j_N_r, j_psi_r, j_N, j_psi. auto_derive; [ nonzero r | field; nonzero r ].
Qed.

Lemma j_N_r_derive r : 1 <= r <= 2 -> is_derive j_N_r r (j_N_rr r).
Proof.
  intros Hr. unfold j_N_rr, j_psi_rr, j_N_r, j_psi, j_psi_r. auto_derive; [ nonzero r | field; nonzero r ].
Qed.

Lemma j_psi_derive r : 1 <= r <= 2 -> is_derive j_psi r (j_psi_r r).
Proof.
  intros Hr. unfold j_psi_r, j_psi. auto_derive; [ nonzero r | field; nonzero r ].
Qed.

Lemma j_psi_r_derive r : 1 <= r <= 2 -> is_derive j_psi_r r (j_psi_rr r).
Proof.
  intros Hr. unfold j_psi_rr, j_psi_r. auto_derive; [ nonzero r | field; nonzero r ].
Qed.

Lemma j_f_derive r : 1 <= r <= 2 -> is_derive j_f r (j_f_r r).
Proof.
  intros Hr. unfold j_f_r, j_f. auto_derive; [ nonzero r | field; nonzero r ].
Qed.

Lemma j_f_r_derive r : 1 <= r <= 2 -> is_derive j_f_r r (j_f_rr r).
Proof.
  intros Hr. unfold j_f_rr, j_f_r. auto_derive; [ nonzero r | field; nonzero r ].
Qed.

(* inside the wall the flat cavity, drifting with the shift of its face, and outside it Schwarzschild's
   exterior of mass 3/2 with no shift: both are empty, and the wall's jets meet theirs to first order at both
   faces *)
Definition cav_N : R := (17 / 47).
Definition cav_psi : R := (47 / 32).
Definition cav_f : R := (1 / 100).
Definition ext_N (r : R) : R := (1 + (4 * (r - 1))) / (7 + (4 * (r - 1))).
Definition ext_N_r (r : R) : R := 24 / ((7 + (4 * (r - 1))) ^ 2).
Definition ext_N_rr (r : R) : R := (-192) / ((7 + (4 * (r - 1))) ^ 3).
Definition ext_psi (r : R) : R := (7 + (4 * (r - 1))) / (4 + (4 * (r - 1))).
Definition ext_psi_r (r : R) : R := (-3) / (4 * (r ^ 2)).
Definition ext_psi_rr (r : R) : R := 3 / (2 * (r ^ 3)).

Lemma meets_cavity : j_N 1 = cav_N /\ j_psi 1 = cav_psi /\ j_f 1 = cav_f /\ j_N_r 1 = 0 /\ j_psi_r 1 = 0 /\ j_f_r 1 = 0.
Proof. unfold j_N, j_N_r, j_psi, j_psi_r, j_f, j_f_r, cav_N, cav_psi, cav_f. repeat split; field; nonzero_at. Qed.

Lemma meets_exterior : j_N 2 = ext_N 2 /\ j_N_r 2 = ext_N_r 2 /\ j_psi 2 = ext_psi 2 /\ j_psi_r 2 = ext_psi_r 2 /\ j_f 2 = 0 /\ j_f_r 2 = 0.
Proof. unfold j_N, j_N_r, j_psi, j_psi_r, j_f, j_f_r, ext_N, ext_N_r, ext_psi, ext_psi_r. repeat split; field; nonzero_at. Qed.

Lemma ext_N_derive r : 2 <= r -> is_derive ext_N r (ext_N_r r).
Proof.
  intros Hr. unfold ext_N, ext_N_r. auto_derive; [ nonzero_at | field; nonzero_at ].
Qed.

Lemma ext_N_r_derive r : 2 <= r -> is_derive ext_N_r r (ext_N_rr r).
Proof.
  intros Hr. unfold ext_N_r, ext_N_rr. auto_derive; [ nonzero_at | field; nonzero_at ].
Qed.

Lemma ext_psi_derive r : 2 <= r -> is_derive ext_psi r (ext_psi_r r).
Proof.
  intros Hr. unfold ext_psi, ext_psi_r. auto_derive; [ nonzero_at | field; nonzero_at ].
Qed.

Lemma ext_psi_r_derive r : 2 <= r -> is_derive ext_psi_r r (ext_psi_rr r).
Proof.
  intros Hr. unfold ext_psi_r, ext_psi_rr. auto_derive; [ nonzero_at | field; nonzero_at ].
Qed.

(* the components in the cavity and in the exterior *)
Definition cE (r th : R) : R := G_00 r (cos th) (sin th) cav_N 0 0 cav_psi 0 0 cav_f 0 0.
Definition ca (r th : R) : R := G_01 r (cos th) (sin th) cav_N 0 0 cav_psi 0 0 cav_f 0 0.
Definition cd (r th : R) : R := G_02 r (cos th) (sin th) cav_N 0 0 cav_psi 0 0 cav_f 0 0.
Definition cS (r th : R) : R := G_11 r (cos th) (sin th) cav_N 0 0 cav_psi 0 0 cav_f 0 0.
Definition cx (r th : R) : R := G_12 r (cos th) (sin th) cav_N 0 0 cav_psi 0 0 cav_f 0 0.
Definition cT (r th : R) : R := G_22 r (cos th) (sin th) cav_N 0 0 cav_psi 0 0 cav_f 0 0.
Definition cP (r th : R) : R := G_33 r (cos th) (sin th) cav_N 0 0 cav_psi 0 0 cav_f 0 0.
Definition oE (r th : R) : R := G_00 r (cos th) (sin th) (ext_N r) (ext_N_r r) (ext_N_rr r) (ext_psi r) (ext_psi_r r) (ext_psi_rr r) 0 0 0.
Definition oa (r th : R) : R := G_01 r (cos th) (sin th) (ext_N r) (ext_N_r r) (ext_N_rr r) (ext_psi r) (ext_psi_r r) (ext_psi_rr r) 0 0 0.
Definition od (r th : R) : R := G_02 r (cos th) (sin th) (ext_N r) (ext_N_r r) (ext_N_rr r) (ext_psi r) (ext_psi_r r) (ext_psi_rr r) 0 0 0.
Definition oS (r th : R) : R := G_11 r (cos th) (sin th) (ext_N r) (ext_N_r r) (ext_N_rr r) (ext_psi r) (ext_psi_r r) (ext_psi_rr r) 0 0 0.
Definition ox (r th : R) : R := G_12 r (cos th) (sin th) (ext_N r) (ext_N_r r) (ext_N_rr r) (ext_psi r) (ext_psi_r r) (ext_psi_rr r) 0 0 0.
Definition oT (r th : R) : R := G_22 r (cos th) (sin th) (ext_N r) (ext_N_r r) (ext_N_rr r) (ext_psi r) (ext_psi_r r) (ext_psi_rr r) 0 0 0.
Definition oP (r th : R) : R := G_33 r (cos th) (sin th) (ext_N r) (ext_N_r r) (ext_N_rr r) (ext_psi r) (ext_psi_r r) (ext_psi_rr r) 0 0 0.

Lemma cavity_empty r th : 0 < r -> cE r th = 0 /\ ca r th = 0 /\ cd r th = 0 /\ cS r th = 0 /\ cx r th = 0 /\ cT r th = 0 /\ cP r th = 0.
Proof.
  intros Hr. unfold cE, ca, cd, cS, cx, cT, cP, G_00, G_01, G_02, G_11, G_12, G_22, G_33, G_00_00, G_00_20, G_01_10, G_02_01, G_11_00, G_11_20, G_12_11, G_22_00, G_22_20, G_33_00, G_33_20, cav_N, cav_psi, cav_f. repeat split; field; nonzero_at.
Qed.

Lemma exterior_empty r th : 2 <= r -> oE r th = 0 /\ oa r th = 0 /\ od r th = 0 /\ oS r th = 0 /\ ox r th = 0 /\ oT r th = 0 /\ oP r th = 0.
Proof.
  intros Hr. unfold oE, oa, od, oS, ox, oT, oP, G_00, G_01, G_02, G_11, G_12, G_22, G_33, G_00_00, G_00_20, G_01_10, G_02_01, G_11_00, G_11_20, G_12_11, G_22_00, G_22_20, G_33_00, G_33_20, ext_N, ext_N_r, ext_N_rr, ext_psi, ext_psi_r, ext_psi_rr. repeat split; field; nonzero_at.
Qed.

(* every energy condition, for every observer, at every point off the centre *)
Theorem spacetime_energy_conditions r th : 0 < r -> 0 <= th <= PI ->
  energy_conditions (region (cE r th) (tE r th) (oE r th) r) (region (ca r th) (ta r th) (oa r th) r) (region (cd r th) (td r th) (od r th) r) (region (cS r th) (tS r th) (oS r th) r) (region (cx r th) (tx r th) (ox r th) r) (region (cT r th) (tT r th) (oT r th) r) (region (cP r th) (tP r th) (oP r th) r).
Proof.
  intros Hr Hth. destruct (Rlt_le_dec r 1) as [H1 | H1].
  - rewrite !region_inside by exact H1. destruct (cavity_empty r th Hr) as (-> & -> & -> & -> & -> & -> & ->). apply empty_conditions.
  - destruct (Rle_lt_dec r 2) as [H2 | H2].
    + rewrite !region_wall by (split; lra). apply shell_energy_conditions; [split; lra | exact Hth].
    + rewrite !region_outside by exact H2. destruct (exterior_empty r th ltac:(lra)) as (-> & -> & -> & -> & -> & -> & ->). apply empty_conditions.
Qed.

End Drag.

(* Rocket shell on 1 <= r <= 2 with E = 1 - 1/5 (2 - r), acceleration 1/200, exhaust factor 5/4.

   G_* are the components of 8 pi T for the rocket family on its null frame in terms of the jets of its
   profile functions, each the sum of its parts G_*_jl times cos th ^ j and sin th ^ l over a power of
   1 + e cos th, and j_* the jets of this shell.  Proved here: the null, weak, strong and dominant energy
   conditions for every observer at every point off the centre, in the wall, in the empty cavity and in
   the exhaust outside, that the radial jets are derivatives of one another and that those in u are
   the ones the exhaust's evolution gives.
   The jets that vanish on this shell are zero in G_*. *)
Module Rocket.

Definition G_kk_00 (r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr : R) : R :=
  (2 * E_r) / (E * r).
Definition G_kk (r c s E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr : R) : R :=
  G_kk_00 r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr.

Definition G_kl_00 (r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr : R) : R :=
  ((E * ((8 * E * m_r) + (8 * E_r * m))) + (r * (((-1) * (U_r ^ 2) * (r ^ 3)) + ((-4) * E * E_r)))) / (4 * (E ^ 2) * (r ^ 2)).
Definition G_kl_10 (r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr : R) : R :=
  ((r * ((E * ((16 * U) + ((-8) * E * W_r) + ((-8) * E_r * W))) + (4 * E * U_r * r))) + ((-8) * W * (E ^ 2))) / (4 * (E ^ 2) * (r ^ 2)).
Definition G_kl_20 (r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr : R) : R :=
  ((U_r ^ 2) * (r ^ 4)) / (4 * (E ^ 2) * (r ^ 2)).
Definition G_kl (r c s E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr : R) : R :=
  G_kl_00 r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr + c * G_kl_10 r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr + c * c * G_kl_20 r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr.

Definition G_ll_00 (r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr : R) : R :=
  ((r * ((r * (((E ^ 2) * (E_r + ((-4) * U * W))) + (E * r * ((4 * (U ^ 2)) + ((-2) * E * U_r * W))))) + ((E ^ 2) * (((-4) * m_u) + ((-4) * E_r * m))))) + (4 * E_r * (E ^ 2) * (m ^ 2))) / (2 * (E ^ 3) * (r ^ 3)).
Definition G_ll_10 (r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr : R) : R :=
  (r * ((r * ((E * ((E * ((4 * W_u) + (U * (4 + (4 * m_r))) + ((-4) * U_r * m) + (4 * E_r * W))) + (8 * E_r * U * m))) + (r * ((E * (((-4) * E_r * U) + (2 * E * U_r))) + (4 * E_u * U))))) + ((E ^ 2) * ((m * (((-12) * U) + ((-8) * E_r * W))) + ((-4) * E * W))))) / (2 * (E ^ 3) * (r ^ 3)).
Definition G_ll_20 (r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr : R) : R :=
  ((r ^ 2) * ((E * r * (((-8) * (U ^ 2)) + (E * (((-4) * U * W_r) + (6 * U_r * W))) + ((-8) * E_r * U * W))) + (W * (E ^ 2) * ((12 * U) + (4 * E_r * W))))) / (2 * (E ^ 3) * (r ^ 3)).
Definition G_ll (r c s E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr : R) : R :=
  G_ll_00 r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr + c * G_ll_10 r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr + c * c * G_ll_20 r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr.

Definition G_k2_01 (r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr : R) : R :=
  ((r * ((E * U_rr) + ((-1) * E_r * U_r))) + (4 * E * U_r)) / (2 * (E ^ 2)).
Definition G_k2 (r c s E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr : R) : R :=
  s * G_k2_01 r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr.

Definition G_l2_01 (r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr : R) : R :=
  ((r * ((E * ((E * ((4 * U_r) + ((-2) * U_rr * m))) + (2 * E_r * U_r * m))) + (r * ((E * ((E * U_rr) + ((-1) * E_r * U_r))) + (2 * E_u * U_r))))) + ((E ^ 2) * ((4 * U) + ((-8) * E_r * W) + ((-8) * U_r * m) + ((-4) * E * W_r)))) / (4 * r * (E ^ 3)).
Definition G_l2_11 (r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr : R) : R :=
  (r * ((E * r * (((-8) * U * U_r) + ((-2) * E_r * U_r * W) + (2 * E * U_rr * W))) + (8 * U_r * W * (E ^ 2)))) / (4 * r * (E ^ 3)).
Definition G_l2 (r c s E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr : R) : R :=
  s * G_l2_01 r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr + c * s * G_l2_11 r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr.

Definition G_22_00 (r E E_r E_u E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr : R) : R :=
  ((r * ((r * (((-4) * E * E_ru) + (4 * E_r * E_u) + ((-3) * E * (U_r ^ 2) * (r ^ 2)))) + ((E ^ 2) * ((E_r * (4 + ((-12) * m_r))) + ((-4) * E * m_rr))))) + (4 * E_r * m * (E ^ 2))) / (4 * (E ^ 3) * (r ^ 2)).
