(* the components in the cavity and in the exterior *)
Definition cE (r th : R) : R := G_00 r (cos th) (sin th) cav_N 0 0 cav_psi 0 0 cav_f 0 0 cav_h 0 0.
Definition ca (r th : R) : R := G_01 r (cos th) (sin th) cav_N 0 0 cav_psi 0 0 cav_f 0 0 cav_h 0 0.
Definition cd (r th : R) : R := G_02 r (cos th) (sin th) cav_N 0 0 cav_psi 0 0 cav_f 0 0 cav_h 0 0.
Definition cS (r th : R) : R := G_11 r (cos th) (sin th) cav_N 0 0 cav_psi 0 0 cav_f 0 0 cav_h 0 0.
Definition cx (r th : R) : R := G_12 r (cos th) (sin th) cav_N 0 0 cav_psi 0 0 cav_f 0 0 cav_h 0 0.
Definition cT (r th : R) : R := G_22 r (cos th) (sin th) cav_N 0 0 cav_psi 0 0 cav_f 0 0 cav_h 0 0.
Definition cP (r th : R) : R := G_33 r (cos th) (sin th) cav_N 0 0 cav_psi 0 0 cav_f 0 0 cav_h 0 0.
