Definition oa (r th : R) : R := G_01 r (cos th) (sin th) (ext_N r) (ext_N_r r) (ext_N_rr r) (ext_psi r) (ext_psi_r r) (ext_psi_rr r) 0 0 0 0 0 0.
Definition od (r th : R) : R := G_02 r (cos th) (sin th) (ext_N r) (ext_N_r r) (ext_N_rr r) (ext_psi r) (ext_psi_r r) (ext_psi_rr r) 0 0 0 0 0 0.
Definition oS (r th : R) : R := G_11 r (cos th) (sin th) (ext_N r) (ext_N_r r) (ext_N_rr r) (ext_psi r) (ext_psi_r r) (ext_psi_rr r) 0 0 0 0 0 0.
Definition ox (r th : R) : R := G_12 r (cos th) (sin th) (ext_N r) (ext_N_r r) (ext_N_rr r) (ext_psi r) (ext_psi_r r) (ext_psi_rr r) 0 0 0 0 0 0.
