Definition bridge_00_family : rx := (RAdd (RDiv (RAdd (RMul (RPow (RA 1) 2) (RAdd (RMul (RMul (RZ (-32)) (RO 4)) (RA 0)) (RMul (RMul (RZ (-16)) (RO 5)) (RPow (RA 0) 2)))) (RMul (RPow (RA 2) 5) (RAdd (RAdd (RMul (RO 6) (RAdd (RAdd (RMul (RZ (-1)) (RO 6)) (RMul (RZ 2) (RO 9))) (RMul (RMul (RZ (-2)) (RO 10)) (RA 0)))) (RMul (RO 9) (RAdd (RMul (RZ (-1)) (RO 9)) (RMul (RMul (RZ 2) (RO 10)) (RA 0))))) (RMul (RMul (RZ (-1)) (RPow (RO 10) 2)) (RPow (RA 0) 2))))) (RMul (RMul (RMul (RZ 4) (RPow (RA 1) 2)) (RPow (RA 2) 5)) (RPow (RA 0) 2))) (RMul (RMul (RO 0) (RO 0)) (RDiv (RMul (RPow (RA 2) 3) (RAdd (RMul (RA 2) (RAdd (RMul (RO 6) (RAdd (RAdd (RMul (RMul (RMul (RZ (-32)) (RO 9)) (RO 4)) (RA 0)) (RMul (RMul (RMul (RZ 16) (RO 7)) (RO 4)) (RPow (RA 0) 2))) (RMul (RMul (RMul (RZ 32) (RO 6)) (RO 4)) (RA 0)))) (RMul (RA 2) (RAdd (RAdd (RMul (RO 6) (RAdd (RAdd (RAdd (RMul (RZ (-10)) (RO 9)) (RMul (RZ 5) (RO 6))) (RMul (RMul (RZ 2) (RO 10)) (RA 0))) (RMul (RMul (RZ 8) (RO 7)) (RA 0)))) (RMul (RO 9) (RAdd (RAdd (RMul (RZ 5) (RO 9)) (RMul (RMul (RZ (-8)) (RO 7)) (RA 0))) (RMul (RMul (RZ (-2)) (RO 10)) (RA 0))))) (RMul (RPow (RO 10) 2) (RPow (RA 0) 2)))))) (RMul (RMul (RMul (RZ 48) (RPow (RO 6) 2)) (RPow (RO 4) 2)) (RPow (RA 0) 2)))) (RMul (RMul (RMul (RZ 4) (RPow (RA 1) 2)) (RPow (RA 2) 5)) (RPow (RA 0) 2))))).
Lemma G_00_family (r c s N N_r N_rr psi psi_r psi_rr f f_r f_rr h h_r h_rr : R) : r <> 0 -> N <> 0 -> psi <> 0 ->
  G_00 r c s N N_r N_rr psi psi_r psi_rr f f_r f_rr h h_r h_rr = DragEinstein.G_00 r c s N N_r N_rr psi psi_r psi_rr f f_r f_rr h h_r h_rr.
Proof.
  intros H0 H1 H2.
  change (rx_eval (r :: N :: psi :: nil) (c :: s :: N_r :: N_rr :: psi_r :: psi_rr :: f :: f_r :: f_rr :: h :: h_r :: h_rr :: nil) bridge_00 = rx_eval (r :: N :: psi :: nil) (c :: s :: N_r :: N_rr :: psi_r :: psi_rr :: f :: f_r :: f_rr :: h :: h_r :: h_rr :: nil) bridge_00_family).
  apply rx_same_correct; [repeat constructor; assumption | vm_compute; reflexivity].
Qed.

Theorem einstein_00 (r c s N N_r N_rr psi psi_r psi_rr f f_r f_rr h h_r h_rr  : R) :
  r <> 0 -> N <> 0 -> psi <> 0 -> s <> 0 -> s * s = 1 - c ^ 2 ->
