Qed.

Lemma row_s r th : 1 <= r <= 2 -> 0 <= th <= PI -> 0 <= mu r th + trace (tE r th) (tS r th) (tT r th) (tP r th) / 2.
Proof.
  intros Hr Hth.
  generalize (radial_nonneg 16 7 radial_prog radial_constants radial_atoms radial_rows radial_ok r th Hr Hth 5 ltac:(simpl; lia)).
  rewrite radial_atoms_eq. exact (fun h => h).
Qed.

Lemma row_d0 r th : 1 <= r <= 2 -> 0 <= th <= PI -> 0 <= D00 (tE r th) (ta r th) (td r th) (lam r th) - Rabs (D01 (tE r th) (ta r th) (td r th) (tS r th) (tx r th)) - Rabs (D02 (tE r th) (ta r th) (td r th) (tx r th) (tT r th)).
Proof.
  intros Hr Hth.
  generalize (radial_nonneg 16 7 radial_prog radial_constants radial_atoms radial_rows radial_ok r th Hr Hth 6 ltac:(simpl; lia)).
  rewrite radial_atoms_eq. exact (fun h => h).
Qed.

Lemma row_d1 r th : 1 <= r <= 2 -> 0 <= th <= PI -> 0 <= D11 (ta r th) (tS r th) (tx r th) (lam r th) - Rabs (D01 (tE r th) (ta r th) (td r th) (tS r th) (tx r th)) - Rabs (D12 (ta r th) (td r th) (tS r th) (tx r th) (tT r th)).
Proof.
  intros Hr Hth.
  generalize (radial_nonneg 16 7 radial_prog radial_constants radial_atoms radial_rows radial_ok r th Hr Hth 7 ltac:(simpl; lia)).
  rewrite radial_atoms_eq. exact (fun h => h).
Qed.

Lemma row_d2 r th : 1 <= r <= 2 -> 0 <= th <= PI -> 0 <= D22 (td r th) (tx r th) (tT r th) (lam r th) - Rabs (D02 (tE r th) (ta r th) (td r th) (tx r th) (tT r th)) - Rabs (D12 (ta r th) (td r th) (tS r th) (tx r th) (tT r th)).
Proof.
  intros Hr Hth.
  generalize (radial_nonneg 16 7 radial_prog radial_constants radial_atoms radial_rows radial_ok r th Hr Hth 8 ltac:(simpl; lia)).
  rewrite radial_atoms_eq. exact (fun h => h).
Qed.

Lemma row_d3 r th : 1 <= r <= 2 -> 0 <= th <= PI -> 0 <= D33 (tP r th) (lam r th).
Proof.
  intros Hr Hth.
  generalize (radial_nonneg 16 7 radial_prog radial_constants radial_atoms radial_rows radial_ok r th Hr Hth 9 ltac:(simpl; lia)).
  rewrite radial_atoms_eq. exact (fun h => h).
Qed.

Lemma row_l r th : 1 <= r <= 2 -> 0 <= th <= PI -> 0 <= lam r th.
Proof.
  intros Hr Hth.
  generalize (radial_nonneg 16 7 radial_prog radial_constants radial_atoms radial_rows radial_ok r th Hr Hth 10 ltac:(simpl; lia)).
  rewrite radial_atoms_eq. exact (fun h => h).
Qed.

(* every energy condition, for every observer, at every point of the wall *)
Theorem shell_energy_conditions r th : 1 <= r <= 2 -> 0 <= th <= PI -> energy_conditions (tE r th) (ta r th) (td r th) (tS r th) (tx r th) (tT r th) (tP r th).
Proof.
  intros Hr Hth.
  apply (certified (tE r th) (ta r th) (td r th) (tS r th) (tx r th) (tT r th) (tP r th) (mu r th) (lam r th)).
  - pose proof (row_n0 r th Hr Hth). lra.
  - pose proof (row_n1 r th Hr Hth). lra.
  - pose proof (row_n2 r th Hr Hth). lra.
  - pose proof (row_n3 r th Hr Hth). lra.
  - pose proof (row_m r th Hr Hth). lra.
  - pose proof (row_s r th Hr Hth). lra.
  - pose proof (row_d0 r th Hr Hth). lra.
  - pose proof (row_d1 r th Hr Hth). lra.
  - pose proof (row_d2 r th Hr Hth). lra.
  - pose proof (row_d3 r th Hr Hth). lra.
  - pose proof (row_l r th Hr Hth). lra.
Qed.

