(* inside the wall the flat cavity, drifting with the shift of its face, and outside it Schwarzschild's
   exterior of mass 8/5 with no shift: both are empty, and the wall's jets meet theirs to first order at both
   faces *)
Definition cav_N : R := (1 / 3).
Definition cav_psi : R := (3 / 2).
Definition cav_f : R := (2457 / 65536).
Definition cav_h : R := (2457 / 65536).
Definition ext_N (r : R) : R := (1 + (5 * (r - 1))) / (9 + (5 * (r - 1))).
Definition ext_N_r (r : R) : R := 40 / ((9 + (5 * (r - 1))) ^ 2).
Definition ext_N_rr (r : R) : R := (-400) / ((9 + (5 * (r - 1))) ^ 3).
Definition ext_psi (r : R) : R := (9 + (5 * (r - 1))) / (5 + (5 * (r - 1))).
Definition ext_psi_r (r : R) : R := (-4) / (5 * (r ^ 2)).
Definition ext_psi_rr (r : R) : R := 8 / (5 * (r ^ 3)).

Lemma meets_cavity : j_N 1 = cav_N /\ j_psi 1 = cav_psi /\ j_f 1 = cav_f /\ j_h 1 = cav_h /\ j_N_r 1 = 0 /\ j_psi_r 1 = 0 /\ j_f_r 1 = 0 /\ j_h_r 1 = 0.
Proof. unfold j_N, j_N_r, j_psi, j_psi_r, j_f, j_f_r, j_h, j_h_r, cav_N, cav_psi, cav_f, cav_h. repeat split; field; nonzero_at. Qed.

Lemma meets_exterior : j_N 2 = ext_N 2 /\ j_N_r 2 = ext_N_r 2 /\ j_psi 2 = ext_psi 2 /\ j_psi_r 2 = ext_psi_r 2 /\ j_f 2 = 0 /\ j_f_r 2 = 0 /\ j_h 2 = 0 /\ j_h_r 2 = 0.
Proof. unfold j_N, j_N_r, j_psi, j_psi_r, j_f, j_f_r, j_h, j_h_r, ext_N, ext_N_r, ext_psi, ext_psi_r. repeat split; field; nonzero_at. Qed.

Lemma ext_N_derive r : 2 <= r -> is_derive ext_N r (ext_N_r r).
Proof.
  intros Hr. unfold ext_N, ext_N_r. auto_derive; [ nonzero_at | field; nonzero_at ].
Qed.

