(* the components in the cavity and in the exterior *)
Definition cE (r th : R) : R := G_00 r (cos th) (sin th) cav_N 0 0 cav_psi 0 0 cav_f 0 0 cav_h 0 0.
Definition ca (r th : R) : R := G_01 r (cos th) (sin th) cav_N 0 0 cav_psi 0 0 cav_f 0 0 cav_h 0 0.
