Lemma exterior_empty r th : 2 <= r -> oE r th = 0 /\ oa r th = 0 /\ od r th = 0 /\ oS r th = 0 /\ ox r th = 0 /\ oT r th = 0 /\ oP r th = 0.
Proof.
  intros Hr. unfold oE, oa, od, oS, ox, oT, oP, G_00, G_01, G_02, G_11, G_12, G_22, G_33, G_00_00, G_00_20, G_01_10, G_02_01, G_11_00, G_11_20, G_12_11, G_22_00, G_22_20, G_33_00, G_33_20, ext_N, ext_N_r, ext_N_rr, ext_psi, ext_psi_r, ext_psi_rr. repeat split; field; nonzero_at.
Qed.

(* every energy condition, for every observer, at every point off the centre *)
Theorem spacetime_energy_conditions r th : 0 < r -> 0 <= th <= PI ->
  energy_conditions (region (cE r th) (tE r th) (oE r th) r) (region (ca r th) (ta r th) (oa r th) r) (region (cd r th) (td r th) (od r th) r) (region (cS r th) (tS r th) (oS r th) r) (region (cx r th) (tx r th) (ox r th) r) (region (cT r th) (tT r th) (oT r th) r) (region (cP r th) (tP r th) (oP r th) r).
Proof.
  intros Hr Hth. destruct (Rlt_le_dec r 1) as [H1 | H1].
  - rewrite !region_inside by exact H1. destruct (cavity_empty r th Hr) as (-> & -> & -> & -> & -> & -> & ->). apply empty_conditions.
  - destruct (Rle_lt_dec r 2) as [H2 | H2].
    + rewrite !region_wall by (split; lra). apply shell_energy_conditions; [split; lra | exact Hth].
    + rewrite !region_outside by exact H2. destruct (exterior_empty r th ltac:(lra)) as (-> & -> & -> & -> & -> & -> & ->). apply empty_conditions.
Qed.

