(* the radial jets are derivatives of one another *)
Lemma j_E_derive r : 1 <= r <= 2 -> is_derive j_E r (j_E_r r).
Proof.
  intros Hr. unfold j_E_r, j_E. auto_derive; [ nonzero r | field; nonzero r ].
Qed.

Lemma j_E_r_derive r : 1 <= r <= 2 -> is_derive j_E_r r (j_E_rr r).
Proof.
  intros Hr. unfold j_E_rr, j_E_r. auto_derive; [ nonzero r | field; nonzero r ].
Qed.

Lemma j_e_derive r : 1 <= r <= 2 -> is_derive j_e r (j_e_r r).
Proof.
  intros Hr. unfold j_e_r, j_e. auto_derive; [ nonzero r | field; nonzero r ].
Qed.

Lemma j_e_r_derive r : 1 <= r <= 2 -> is_derive j_e_r r (j_e_rr r).
Proof.
  intros Hr. unfold j_e_rr, j_e_r. auto_derive; [ nonzero r | field; nonzero r ].
Qed.

Lemma j_e_u_derive r : 1 <= r <= 2 -> is_derive j_e_u r (j_e_ru r).
Proof.
  intros Hr. unfold j_e_ru, j_e_u. auto_derive; [ nonzero r | field; nonzero r ].
Qed.

Lemma j_U_derive r : 1 <= r <= 2 -> is_derive j_U r (j_U_r r).
Proof.
  intros Hr. unfold j_U_r, j_U. auto_derive; [ nonzero r | field; nonzero r ].
Qed.

