Lemma row_n0 r th : 1 <= r <= 2 -> 0 <= th <= PI -> 0 <= tE r th - mu r th - Rabs (ta r th) - Rabs (td r th).
Proof.
  intros Hr Hth.
  generalize (radial_nonneg 16 7 radial_prog radial_constants radial_atoms radial_rows radial_ok r th Hr Hth 0 ltac:(simpl; lia)).
  rewrite radial_atoms_eq. exact (fun h => h).
Qed.

Lemma row_n1 r th : 1 <= r <= 2 -> 0 <= th <= PI -> 0 <= tS r th + mu r th - Rabs (ta r th) - Rabs (tx r th).
Proof.
  intros Hr Hth.
  generalize (radial_nonneg 16 7 radial_prog radial_constants radial_atoms radial_rows radial_ok r th Hr Hth 1 ltac:(simpl; lia)).
  rewrite radial_atoms_eq. exact (fun h => h).
Qed.

