Lemma row_s r th : 1 <= r <= 2 -> 0 <= th <= PI -> 0 <= mu r th + trace (tE r th) (tS r th) (tT r th) (tP r th) / 2.
Proof.
  intros Hr Hth.
  generalize (radial_nonneg 16 7 radial_prog radial_constants radial_atoms radial_rows radial_ok r th Hr Hth 5 ltac:(simpl; lia)).
