Qed.

Lemma row_d0 r th : 1 <= r <= 2 -> 0 <= th <= PI -> 0 <= D00 (tE r th) (ta r th) (td r th) (lam r th) - Rabs (D01 (tE r th) (ta r th) (td r th) (tS r th) (tx r th)) - Rabs (D02 (tE r th) (ta r th) (td r th) (tx r th) (tT r th)).
Proof.
  intros Hr Hth.
  generalize (radial_nonneg 16 7 radial_prog radial_constants radial_atoms radial_rows radial_ok r th Hr Hth 6 ltac:(simpl; lia)).
  rewrite radial_atoms_eq. exact (fun h => h).
Qed.

Lemma row_d1 r th : 1 <= r <= 2 -> 0 <= th <= PI -> 0 <= D11 (ta r th) (tS r th) (tx r th) (lam r th) - Rabs (D01 (tE r th) (ta r th) (td r th) (tS r th) (tx r th)) - Rabs (D12 (ta r th) (td r th) (tS r th) (tx r th) (tT r th)).
Proof.
