Lemma row_H0 r th : 1 <= r <= 2 -> 0 <= th <= PI -> 0 <= H0 r - (399999 / 1000000).
Proof.
  intros Hr Hth.
  generalize (radial_nonneg 16 7 radial_prog radial_constants radial_atoms radial_rows radial_ok r th Hr Hth 11 ltac:(simpl; lia)).
  rewrite radial_atoms_eq. exact (fun h => h).
Qed.

Lemma H0_positive r : 1 <= r <= 2 -> 0 < H0 r.
Proof. intros Hr. pose proof (row_H0 r 0 Hr (conj (Rle_refl 0) (Rlt_le _ _ PI_RGT_0))). lra. Qed.

(* every energy condition, for every observer, at every point of the wall *)
Theorem shell_energy_conditions r th : 1 <= r <= 2 -> 0 <= th <= PI -> energy_conditions (tE r th) (ta r th) (td r th) (tS r th) (tx r th) (tT r th) (tP r th).
Proof.
  intros Hr Hth.
  apply (certified (tE r th) (ta r th) (td r th) (tS r th) (tx r th) (tT r th) (tP r th) (mu r th) (lam r th)).
  - pose proof (row_n0 r th Hr Hth). lra.
  - pose proof (row_n1 r th Hr Hth). lra.
  - pose proof (row_n2 r th Hr Hth). lra.
  - pose proof (row_n3 r th Hr Hth). lra.
  - pose proof (row_m r th Hr Hth). lra.
  - pose proof (row_s r th Hr Hth). lra.
  - pose proof (row_d0 r th Hr Hth). lra.
  - pose proof (row_d1 r th Hr Hth). lra.
  - pose proof (row_d2 r th Hr Hth). lra.
  - pose proof (row_d3 r th Hr Hth). lra.
  - pose proof (row_l r th Hr Hth). lra.
Qed.

(* G_* are the rocket family's G_* at this shell's jets, and so its Einstein tensor on the frame there *)
Definition bridge_kk : rx := (RDiv (RMul (RZ 2) (RO 2)) (RMul (RA 1) (RA 0))).
Definition bridge_kk_family : rx := (RDiv (RMul (RZ 2) (RO 2)) (RMul (RA 1) (RA 0))).
Lemma G_kk_family (r c s E E_r E_u E_rr E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr : R) : r <> 0 -> E <> 0 ->
  G_kk r c s E E_r E_u E_rr E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr = RocketEinstein.G_kk r c s E E_r E_u E_rr E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r 0 U_rr 0.
Proof.
  intros H0 H1.
  change (rx_eval (r :: E :: nil) (c :: s :: E_r :: E_u :: E_rr :: E_ru :: m :: m_r :: m_u :: m_rr :: m_ru :: W :: W_r :: W_u :: W_rr :: W_ru :: U :: U_r :: U_rr :: nil) bridge_kk = rx_eval (r :: E :: nil) (c :: s :: E_r :: E_u :: E_rr :: E_ru :: m :: m_r :: m_u :: m_rr :: m_ru :: W :: W_r :: W_u :: W_rr :: W_ru :: U :: U_r :: U_rr :: nil) bridge_kk_family).
  apply rx_same_correct; [repeat constructor; assumption | vm_compute; reflexivity].
Qed.

Theorem einstein_kk (r c s E E_r E_u E_rr E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr E_uu m_uu W_uu U_uu : R) :
  r <> 0 -> E <> 0 -> s <> 0 -> s * s = 1 - c ^ 2 ->
  RocketEinstein.einstein (r :: E :: s * s :: nil) (c :: E_r :: E_u :: E_rr :: E_ru :: m :: m_r :: m_u :: m_rr :: m_ru :: W :: W_r :: W_u :: W_rr :: W_ru :: U :: U_r :: 0 :: U_rr :: 0 :: E_uu :: m_uu :: W_uu :: U_uu :: nil) RocketEinstein.fk RocketEinstein.fk = G_kk r c s E E_r E_u E_rr E_ru m m_r m_u m_rr m_ru W W_r W_u W_rr W_ru U U_r U_rr.
Proof.
  intros. rewrite G_kk_family by assumption. apply RocketEinstein.einstein_kk; assumption.
Qed.

